#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "mvt.h"

/* ---------------------------------------------------------------
 * Tunable blocking parameters for the main kernel.
 *
 * These control the tile sizes used when traversing the matrix in
 * kernel_mvt. They can be overridden at compile time, e.g.:
 *
 *   gcc -DMVT_BLOCK_SIZE_I=64 -DMVT_BLOCK_SIZE_J=64 ...
 *
 * Choose them to match the target machine's cache hierarchy.
 * --------------------------------------------------------------- */
#ifndef MVT_BLOCK_SIZE_I
# define MVT_BLOCK_SIZE_I 32
#endif

#ifndef MVT_BLOCK_SIZE_J
# define MVT_BLOCK_SIZE_J 32
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x1[i] = (DATA_TYPE) (i % n) / n;
      x2[i] = (DATA_TYPE) ((i + 1) % n) / n;
      y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
      y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
      for (j = 0; j < n; j++)
	A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Use local restrict-qualified pointers to convey the true
     aliasing properties to the optimizer. We only access the
     arrays through these pointers inside the kernel. */
  DATA_TYPE *restrict x1p = x1;
  DATA_TYPE *restrict x2p = x2;
  DATA_TYPE *restrict y1p = y_1;
  DATA_TYPE *restrict y2p = y_2;
  DATA_TYPE (*restrict Ap)[n] = (DATA_TYPE (*restrict)[n])A;

  int i, j, ii, jj;

#pragma scop
  /* -----------------------------------------------------------
   * Optimized kernel:
   *
   * Original code (two separate matrix-vector products):
   *
   *   // x1 = x1 + A * y_1
   *   for (i = 0; i < _PB_N; i++)
   *     for (j = 0; j < _PB_N; j++)
   *       x1[i] = x1[i] + A[i][j] * y_1[j];
   *
   *   // x2 = x2 + A^T * y_2
   *   for (i = 0; i < _PB_N; i++)
   *     for (j = 0; j < _PB_N; j++)
   *       x2[i] = x2[i] + A[j][i] * y_2[j];
   *
   * Observations:
   * - Mathematically, the second expression is x2 = A^T * y_2.
   *   For each matrix element A[i][j], its contribution to x2
   *   can equivalently be written as:
   *
   *       x2[j] += A[i][j] * y_2[i];
   *
   *   This is algebraically identical and, importantly, for each
   *   element x2[k] the *sequence* of summands A[?][k]*y_2[?]
   *   is still applied in increasing index order, so the
   *   floating-point accumulation order for each x2[k] remains
   *   identical to the original code (bit-for-bit identical
   *   results).
   *
   * - Using this equivalent form allows us to:
   *     * Fuse the two loops, so each A[i][j] is loaded once and
   *       used for both x1 and x2.
   *     * Traverse A in row-major order only (contiguous access).
   *     * Stream through y_1 and x2 contiguously.
   *
   * - We additionally apply simple blocking (tiling) over i and j
   *   using MVT_BLOCK_SIZE_I and MVT_BLOCK_SIZE_J. This improves
   *   cache reuse of x2 and y_1 when N is large. The blocking
   *   preserves the per-element accumulation order:
   *     * For each fixed i, j still visits 0.._PB_N-1 in order.
   *     * For each fixed j, i still visits 0.._PB_N-1 in order.
   *   Hence floating-point semantics for x1 and x2 are preserved.
   * ----------------------------------------------------------- */
  for (ii = 0; ii < _PB_N; ii += MVT_BLOCK_SIZE_I)
    {
      int i_max = ii + MVT_BLOCK_SIZE_I;
      if (i_max > _PB_N)
        i_max = _PB_N;

      for (i = ii; i < i_max; ++i)
        {
          /* Keep the running sum for x1[i] in a register. */
          DATA_TYPE xi = x1p[i];
          /* y2[i] is invariant across the inner j-loop. */
          const DATA_TYPE y2_i = y2p[i];

          for (jj = 0; jj < _PB_N; jj += MVT_BLOCK_SIZE_J)
            {
              int j_max = jj + MVT_BLOCK_SIZE_J;
              if (j_max > _PB_N)
                j_max = _PB_N;

              /* Inner-most loop: contiguous in both A[i][j] and x2[j]. */
              for (j = jj; j < j_max; ++j)
                {
                  const DATA_TYPE Aij = Ap[i][j];

                  /* x1 = x1 + A * y_1 (row i · vector y_1). */
                  xi     += Aij * y1p[j];

                  /* x2 = x2 + A^T * y_2, using equivalent form:
                     x2[j] += A[i][j] * y_2[i]. */
                  x2p[j] += Aij * y2_i;
                }
            }

          x1p[i] = xi;
        }
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
