      y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
      y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;

      /* Use a row pointer to improve locality and reduce address arithmetic. */
      DATA_TYPE *Ai = A[i];
      for (j = 0; j < n; j++)
        Ai[j] = (DATA_TYPE) ((i * j) % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:

   - The two original matrix-vector products

       x1[i] += sum_j A[i][j] * y_1[j]
       x2[i] += sum_j A[j][i] * y_2[j]

     are algebraically fused into a single doubly-nested loop:

       for each (i, j):
         x1[i] += A[i][j] * y_1[j];
         x2[j] += A[i][j] * y_2[i];

     This uses each A[i][j] once instead of twice and accesses A only
     in row-major order (contiguous memory), greatly improving cache
     behavior compared to the original column-wise traversal for x2.

   - x1[i] is kept in a scalar register (x1_i) during the inner loop
     to avoid repeated loads/stores.

   The mathematical result is unchanged:

     x1'_i = x1_i + sum_j A[i][j] * y_1[j]          (unchanged)
     x2'_j = x2_j + sum_i A[i][j] * y_2[i]
           = x2_j + sum_i A[i][j] * y_2[i]
           = x2_j + sum_i A[i][j] * y_2[i]
           (same as original x2[i] += sum_j A[j][i] * y_2[j]
            after renaming indices).
*/
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  /* Fused, cache-friendly kernel. */
  for (i = 0; i < _PB_N; i++)
    {
      /* Keep x1[i] in a register for the whole inner loop. */
      DATA_TYPE x1_i      = x1[i];
      const DATA_TYPE y2_i = y_2[i];

      /* Pointer to the i-th row of A to reduce address arithmetic. */
      DATA_TYPE *Ai = A[i];

      for (j = 0; j < _PB_N; j++)
        {
          const DATA_TYPE A_ij = Ai[j];

          /* Original first kernel: x1[i] += A[i][j] * y_1[j]; */
          x1_i += A_ij * y_1[j];

          /* Original second kernel, rewritten:
             x2[j] += A[i][j] * y_2[i];
             This is algebraically equivalent to:
               x2[i] += A[j][i] * y_2[j]
             after swapping the roles of i and j in the sum. */
          x2[j] += A_ij * y2_i;
        }

      /* Store back the accumulated value for this row. */
      x1[i] = x1_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
