/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Effective iteration bounds (PolyBench may use _PB_N <= n). */
  const int N_iter = _PB_N;
  const int N_full = n; /* actual leading dimension of A */

  /* Local restricted views to help the compiler with alias analysis and
   * vectorization. The PolyBench allocation guarantees that these arrays
   * do not overlap in memory. */
  DATA_TYPE *restrict x1_ = x1;
  DATA_TYPE *restrict x2_ = x2;
  DATA_TYPE *restrict y1_ = y_1;
  DATA_TYPE *restrict y2_ = y_2;
  DATA_TYPE *restrict A_  = &A[0][0];

#pragma scop
  /* Optimized, fused kernel:
   *
   * Original code:
   *
   *   for (i = 0; i < N; i++)
   *     for (j = 0; j < N; j++)
   *       x1[i] += A[i][j] * y_1[j];
   *
   *   for (i = 0; i < N; i++)
   *     for (j = 0; j < N; j++)
   *       x2[i] += A[j][i] * y_2[j];
   *
   * Algebraically, this is equivalent to:
   *
   *   for all i, j:
   *     x1[i] += A[i][j] * y_1[j];
   *     x2[j] += A[i][j] * y_2[i];
   *
   * which we implement below.  Each matrix element A[i][j] is loaded once
   * and reused for both x1 and x2 updates.  The matrix A is traversed by
   * rows (contiguous in memory), and x2 is updated in a streaming fashion,
   * improving cache locality and enabling efficient vectorization.
   */
  for (i = 0; i < N_iter; ++i)
  {
    /* Keep x1[i] in a register for the whole row and read y2[i] once. */
    DATA_TYPE x1_i       = x1_[i];
    const DATA_TYPE y2_i = y2_[i];

    /* Pointer to the beginning of row i of A.  Row stride is N_full. */
    const size_t row_offset = (size_t)i * (size_t)N_full;
    DATA_TYPE *restrict A_row = A_ + row_offset;

    /* Main compute loop: j dimension is contiguous for A_row, y1_, and x2_. */
#pragma GCC ivdep
    for (j = 0; j < N_iter; ++j)
    {
      const DATA_TYPE a_ij = A_row[j];
      x1_i    += a_ij * y1_[j];
      x2_[j]  += a_ij * y2_i;
    }

    x1_[i] = x1_i;
  }
#pragma endscop
}


int main(int argc, char** argv)
{
