/* -------------------------------------------------------------------------
 * Tunable blocking parameters for the kernel.
 *
 * MVT_BLOCK_SIZE_X2_I controls the size of the i-block used when computing
 * x2 += A^T * y2. It can be changed at compile time, e.g.:
 *
 *   gcc -O3 -DMVT_BLOCK_SIZE_X2_I=64 ...
 *
 * to tune for a particular cache hierarchy / micro-architecture.
 * ------------------------------------------------------------------------- */
#ifndef MVT_BLOCK_SIZE_X2_I
# define MVT_BLOCK_SIZE_X2_I 32
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;
  /* Precompute reciprocal of n once to avoid repeated divisions. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      /* NOTE: (i % n) == i because 0 <= i < n, but we keep the original
         form for y_1 and y_2 to preserve the intended periodic behavior. */
      x1[i]  = (DATA_TYPE)(i % n) * inv_n;
      x2[i]  = (DATA_TYPE)((i + 1) % n) * inv_n;
      y_1[i] = (DATA_TYPE)((i + 3) % n) * inv_n;
      y_2[i] = (DATA_TYPE)((i + 4) % n) * inv_n;

      /* Work with a row pointer to improve locality and help the compiler. */
      DATA_TYPE *restrict Ai = A[i];
      for (j = 0; j < n; j++)
        Ai[j] = (DATA_TYPE)((i * j) % n) * inv_n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x1,N,n),
		 DATA_TYPE POLYBENCH_1D(x2,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x1");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation:

     for i in [0..N)
       for j in [0..N)
         x1[i] += A[i][j] * y_1[j];

     for i in [0..N)
       for j in [0..N)
         x2[i] += A[j][i] * y_2[j];

   Optimizations applied:

   - For x1:
       * Keep the original row-major traversal (good spatial locality for A).
       * Use a local accumulator for x1[i] and a row pointer for A[i] to
         encourage the compiler to keep values in registers and vectorize
         the inner loop as a reduction.

   - For x2:
       * The naive loop order has good temporal locality for x2[i] (each
         element is loaded/stored once) but very poor spatial locality for
         A[j][i] (strided access across rows).
       * We apply a register-blocked algorithm over the i-dimension:

           for ii in blocks of size B (MVT_BLOCK_SIZE_X2_I):
             load x2[ii : ii+B) into a small buffer x2_tile[]
             for j in [0..N):
               y2j = y_2[j]
               use the contiguous slice A[j][ii : ii+B) to update x2_tile[]
             store x2_tile[] back to x2[ii : ii+B)

         This preserves the original arithmetic result exactly:
           x2[i] <- x2[i] + sum_j A[j][i] * y_2[j]

         while:
           - keeping the number of loads/stores of x2 at O(N) (each element
             loaded and stored once), as in the original code;
           - turning the access to A into contiguous segments along the
             innermost loop (good for cache and vectorization);
           - reducing the total number of y_2 loads by a factor of roughly
             MVT_BLOCK_SIZE_X2_I (since each block reuses the y_2 vector).
*/
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Create local restrict-qualified aliases to help the optimizer.
     The program passes non-overlapping arrays, so this preserves
     the original semantics while enabling better vectorization. */
  DATA_TYPE *restrict x1_  = x1;
  DATA_TYPE *restrict x2_  = x2;
  DATA_TYPE *restrict y1_  = y_1;
  DATA_TYPE *restrict y2_  = y_2;
  DATA_TYPE (*restrict A_)[n] = A;

  const int nPB = _PB_N;

#pragma scop
  /* -----------------------------------------------------------------------
   * First part: x1[i] += sum_j A[i][j] * y1[j]
   * Row-major traversal of A (good spatial locality).
   * --------------------------------------------------------------------- */
  for (int i = 0; i < nPB; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE xi = x1_[i];

    /* Inner product of row Ai with vector y1_. */
    for (int j = 0; j < nPB; j++)
    {
      xi += Ai[j] * y1_[j];
    }

    x1_[i] = xi;
  }

  /* -----------------------------------------------------------------------
   * Second part: x2[i] += sum_j A[j][i] * y2[j]
   *
   * We compute this as a blocked algorithm over the i dimension to get:
   *   - contiguous access to slices of A[j][ii : ii+block)
   *   - each x2[i] still loaded/stored exactly once
   * --------------------------------------------------------------------- */
  for (int ii = 0; ii < nPB; ii += MVT_BLOCK_SIZE_X2_I)
  {
    const int i_end     = (ii + MVT_BLOCK_SIZE_X2_I < nPB) ? (ii + MVT_BLOCK_SIZE_X2_I) : nPB;
    const int tile_size = i_end - ii;

    /* Small tile buffer to keep partial sums of x2 in registers/L1. */
    DATA_TYPE x2_tile[MVT_BLOCK_SIZE_X2_I];

    /* Initialize tile from x2. Each element is read once overall. */
    for (int i_local = 0; i_local < tile_size; i_local++)
      x2_tile[i_local] = x2_[ii + i_local];

    /* For each row j, use the contiguous slice A[j][ii : i_end) and update
       all entries of the x2 tile. */
    for (int j = 0; j < nPB; j++)
    {
      const DATA_TYPE y2j = y2_[j];
      DATA_TYPE *restrict A_row_block = &A_[j][ii];

      for (int i_local = 0; i_local < tile_size; i_local++)
      {
        x2_tile[i_local] += A_row_block[i_local] * y2j;
      }
    }

    /* Write the updated tile back to x2. Each element is written once. */
    for (int i_local = 0; i_local < tile_size; i_local++)
      x2_[ii + i_local] = x2_tile[i_local];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
